do $$ declare expression text; begin select pg_get_expr(conbin,conrelid) into strict expression from pg_constraint where conrelid='public.admin_security_events'::regclass and conname='admin_security_events_action_check'; alter table public.admin_security_events drop constraint admin_security_events_action_check; execute format('alter table public.admin_security_events add constraint admin_security_events_action_check check ((%s) or action = ''user_removed'')',expression);end $$;
